"""PowerShell 调用的结果对象。"""


class PSResult(object):
    """一次 PowerShell 调用的结果。"""

    __slots__ = ("exit_code", "stdout", "stderr")

    def __init__(self, exit_code, stdout, stderr=""):
        self.exit_code = int(exit_code)
        self.stdout = stdout
        self.stderr = stderr

    @property
    def ok(self):
        """调用是否成功。"""
        return self.exit_code == 0

    @property
    def output(self):
        """标准输出（去掉首尾空白）。"""
        return self.stdout.strip()

    def __repr__(self):
        return "PSResult(exit_code=%r, ok=%r)" % (self.exit_code, self.ok)


class PSJob(object):
    """一段待执行的 PowerShell 脚本。"""

    def __init__(self, script, name="job"):
        self.script = script
        self.name = name

    def run(self, runner, timeout=None):
        """用 ``runner`` 执行本作业。"""
        return runner(self.script, timeout=timeout)

    def __repr__(self):
        return "PSJob(%r)" % (self.name,)

"""wjob 使用的异常类型。"""


class WJobError(Exception):
    """本库所有异常的基类。"""


class PowerShellError(WJobError):
    """PowerShell 无法启动或返回了不可用的结果。"""

"""wjob 的基础行为测试（仓库自带，不得修改）。"""

import pytest

from wjob import find_powershell, run_script


def test_powershell_is_available():
    assert find_powershell()


def test_simple_output():
    result = run_script("Write-Output 'hello'")
    assert result.stdout.strip() == "hello"


def test_ok_property_is_true_on_success():
    assert run_script("Write-Output 1").ok is True


def test_result_repr_mentions_exit_code():
    result = run_script("Write-Output 1")
    assert "exit_code" in repr(result)


def test_environment_info_lists_powershell():
    from wjob import environment_info

    assert environment_info()["powershell"]

